update_rule.pseudocode:
for each person p:
  schedule = draw_daily_schedule(p.occupation, day_of_week)
  for each time_block in schedule:
    L = select_location_of_type(time_block.type, near=household_of(p))
    if L not at capacity:
      assign p to L for block; else assign overflow to similar L
  set p.current_location_id = last_block_location
for each location L:
  update L.current_occupants from assigned persons

for each retailer r:
  if day % r.supply_delay == 0:
    for type in [cloth,surgical,N95]:
      r.inventory_masks[type] += r.restock_rate[type]
  compute demand_today[type] from persons attempting to purchase
  for each person p with has_masks_inventory < inventory_threshold:
    budget = mask_budget_fraction_of_income * p.income
    choose type maximizing protection per price within budget and availability
    if retailer with inventory exists and price[type] <= budget:
      decrement inventory; p.has_masks_inventory += pack_size; record CostFlows
    else:
      add to backlog if allowed
  for each retailer r:
    adjust price_per_mask[type] *= (1 + price_adjustment_sensitivity * (demand_today[type] - r.restock_rate[type]) / max(1, r.restock_rate[type]))
    clip prices to bounds

mandate_active = (day >= mandate_start_day)
if mandate_active:
  for each location type in mandate_coverage:
    Policy.status_by_location_type[type] = 'required'
else:
  for each type: Policy.status_by_location_type[type] = 'none'
checks_budget = enforcement_resources_per_1k * (population_size / 1000)
Enforcement.actions_today = 0
for each location L with policy 'required':
  for each person p present at L and not compliant_today:
    apply_check = Bernoulli(enforcement_probability * L.enforcement_strength)
    if apply_check and checks_budget > 0:
      issue penalty_amount; record action; checks_budget -= 1; p.last_enforcement_outcome='penalty'
Enforcement.expected_penalty = enforcement_probability * penalty_amount

Epidemiology.new_infections_today = 0
for each location L:
  contacts_per_person = Poisson(L.baseline_contact_rate * contact_rate_multiplier_by_type(L.type))
  for each infectious person i in L:
    for c in 1..contacts_per_person(i):
      choose random target t ≠ i among L.current_occupants
      if t.health_state == 'S':
        e_out = mask_outward_eff(i.mask_type)
        e_in = mask_inward_eff(t.mask_type)
        p_trans = base_transmission_probability_per_contact * (1 - e_out) * (1 - e_in) * L.ventilation_or_risk_level * environmental_risk_scaler
        infected = Bernoulli(p_trans)
        if infected:
          t.health_state = 'E'; t.days_in_state = 0; Epidemiology.new_infections_today += 1

for each person p:
  if p.health_state in ['E','I']:
    p.days_in_state += 1
  if p.health_state == 'E' and p.days_in_state >= incubation_period_mean_days:
    p.health_state = 'I'; p.days_in_state = 0; p.symptomatic = Bernoulli(1 - asymptomatic_fraction)
  if p.health_state == 'I' and p.days_in_state >= infectious_period_mean_days:
    p.health_state = 'R'; p.days_in_state = 0; p.symptomatic = false
Epidemiology.prevalence_I = (# persons with state 'I') / population_size

new_inf = Epidemiology.new_infections_today
prevalence_I = Epidemiology.prevalence_I
cumulative_infections += new_inf
// Epi-estimator for Rt: ratio of new infections to infections shifted by serial interval ~ 5 days
if day >= 5:
  Rt = new_infections_daily[day] / max(1, new_infections_daily[day-5])
else:
  Rt = NaN or 0
emit observables
